head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.vScrenID = 'ULDSTF30005.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_getParam = function() {
    var vTemp = frame.FrameID;
    var Temp2 = vTemp.split("|")[1];
    var vISUR_CD = Temp2.split("=")[1];
    $c.stf.setObjectValue(txb_ISUR_CD, vISUR_CD);
};
scwin.fn_resizeToWin = function() {
    frame.Width = 480;
    frame.Height = 530;
};
scwin.fn_HideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    $c.stf.showObj(panel_debug, false);
};
scwin.fn_Init = function() {
    scwin.fn_listDsclForReg();
};
scwin.fn_listDsclForReg = function() {
    //var MARKET_FLAG = getObjectValue(rdo_Tab1_Market_Flag);	
    var url = "/DisclosureSchedule.do?method=listDsclForReg";
    url += "&SEARCH_TYP=N";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Discls.DataID = encodeURI(url);
    dts_Discls.Reset();
};
scwin.setAcpt_No = async function(GridID, row, ColID) {
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    var vFORM_CD = objDataID.getCellData(row, "ACPT_NO");
    var vFORM_KOR_NM = objDataID.getCellData(row, "DISCLS_TITLE");
    var vDISCLS_PUBL_DDTM = objDataID.getCellData(row, "DISCLS_PUBL_DDTM");
    var parentWin = $c.frame.path("../");
    $c.stf.setObjectValue(parentWin.txb_ACPT_NO, vFORM_CD);
    $c.stf.setObjectValue(parentWin.txb_RptNm, vFORM_KOR_NM);
    if (parentWin.edt_DISCLS_PUBL_DDTM != null) {
        $c.stf.setObjectValue(parentWin.edt_DISCLS_PUBL_DDTM, vDISCLS_PUBL_DDTM);
    } else {
        //메모일정 사용
        parentWin.txb_DISCLS_PUBL_DDTM.setValue(vDISCLS_PUBL_DDTM);
    }
    //여러일정등록화면 관리기간 시작일 입력 위해 추가 2020.09.04
    if (parentWin.edt_SDate != null) {
        $c.stf.setObjectValue(parentWin.edt_SDate, vDISCLS_PUBL_DDTM);
    }
    await $c.frame.CloseFrame();
};
scwin.dts_Discls_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
};
scwin.grd_Discls_OnDblClick = function(row, colid) {
    scwin.setAcpt_No(grd_Discls, row, colid);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    scwin.fn_resizeToWin();
    scwin.fn_getParam();
    scwin.fn_Init();
};
